import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"Docker","description":"Run KiriVers from the multi-arch image kirizuofficial/kirivers against an external PostgreSQL; amd64 and arm64 only.","frontmatter":{"title":"Docker","description":"Run KiriVers from the multi-arch image kirizuofficial/kirivers against an external PostgreSQL; amd64 and arm64 only."},"headers":[],"relativePath":"en/guide/install/docker.md","filePath":"en/guide/install/docker.md","lastUpdated":1790057721000}`),a={name:`en/guide/install/docker.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to “Docker”">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Image name</p><p>The published name is <strong><code>kirizuofficial/kirivers</code></strong>. Which tag to pull follows the current Docker Hub and GitHub Release. Official images already embed the admin console; mounting or copying <code>frontend/dist</code> is unnecessary.</p></div><table tabindex="0"><thead><tr><th>Tag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>latest</code></td><td>points at the most recent release</td></tr><tr><td><code>&lt;semver&gt;</code> (e.g. <code>0.3.0</code>, no <code>v</code> prefix)</td><td>that version&#39;s multi-arch manifest; <code>docker pull</code> picks your architecture</td></tr><tr><td><code>&lt;semver&gt;_amd64</code> / <code>&lt;semver&gt;_arm64</code></td><td>that version&#39;s single-architecture images; use them only when you pin an architecture</td></tr></tbody></table><p>The image supports <code>linux/amd64</code> and <code>linux/arm64</code> (Alpine base, musl builds). Other Linux architectures have no official image — use the <a href="/en/guide/install/#releases-files">glibc Release archives</a> or build from source.</p><p>The image is the published unit; the container is the running unit.</p><p>PostgreSQL must already exist (another container, a hosted database, or the host). This <code>docker run</code> does not start a database. To bring up the database in one stack, use <a href="/en/guide/install/compose">Compose</a>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to “Run”">​</a></h2><p>Mount a host config directory into the container (it must contain <code>config.yaml</code>, <code>admin.yaml</code>, <code>client.yaml</code>) and publish both planes&#39; ports:</p><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kirivers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unless-stopped</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8081:8081</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/kirivers/config:/config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> KIRIVERS_CONFIG=/config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> KIRIVERS_POSTGRES_DSN=&#39;host=host.docker.internal user=kirivers password=CHANGE_ME dbname=kirivers port=5432 sslmode=disable&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  kirizuofficial/kirivers</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Expect the container to stay running and <code>docker logs kirivers</code> to show the <code>:8080</code> / <code>:8081</code> listeners. Open <code>http://127.0.0.1:8081</code> on the host.</p><p>The official image includes the admin console. <code>static_dir</code> in <code>admin.yaml</code> points at the console&#39;s static files; the VitePress docs <code>dist</code> is not the console. <code>static_dir: &quot;&quot;</code> disables the UI.</p><details class="details custom-block"><summary>Container is up but the browser has no login page</summary><p>Confirm port <code>8081</code> is published and <code>static_dir</code> in the container&#39;s <code>admin.yaml</code> is not the empty string. The official image already embeds the UI; do not mount a self-built <code>frontend/dist</code> on top of it.</p></details><h2 id="logs-upgrade-data" tabindex="-1">Logs, upgrade, data <a class="header-anchor" href="#logs-upgrade-data" aria-label="Permalink to “Logs, upgrade, data”">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Action</th></tr></thead><tbody><tr><td>Logs</td><td><code>docker logs -f kirivers</code>; optionally bind-mount <code>log.file.dir</code> to a volume</td></tr><tr><td>Upgrade image</td><td><code>docker pull kirizuofficial/kirivers</code> then recreate the container; back up PostgreSQL and <code>storage.local.root</code> first</td></tr><tr><td>Data</td><td>Database on the PostgreSQL volume; packages on object storage or a <code>storage.local.root</code> volume</td></tr></tbody></table><p>Next: <a href="/en/guide/install/compose">Compose</a> or <a href="/en/guide/config/bootstrap-admin">bootstrap the first admin</a>.</p>`,15)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};